settings.custom_liquid:
{%- comment -%}
  FAQ accordion + FAQPage JSON-LD -- AEO sprint, Week 2 Day 1.
  Self-filters to 7 specific PDPs by handle; renders nothing on any
  other product. Every answer is sourced from copy already live
  elsewhere on this site (see PR notes for exact sources) -- nothing
  here is newly invented marketing copy. Visible text and JSON-LD text
  are generated from the same assigned variables so they always match
  word for word.
{%- endcomment -%}
{%- liquid
  assign faq_handles = 'eclat-14k-gold-vermeil-necklace,the-cobalt-edition-necklace,miro-spanish-dancer-earrings,miro-blue-necklace,miro-femme-et-oiseaux-golden-necklace,bauhaus-purple-red-earrings,architect-enamel-copper-earrings' | split: ','
  assign faq_show = false
  for h in faq_handles
    if product.handle == h
      assign faq_show = true
    endif
  endfor
-%}
{%- if faq_show -%}
  {%- liquid
    assign faq_is_miro = false
    if product.title contains 'Miró' or product.title contains 'Miro'
      assign faq_is_miro = true
    endif

    assign faq_material = product.metafields.general.materials.value
    if faq_material == blank
      assign faq_material_slug = product.metafields['shopify']['jewelry-material'].value
      if faq_material_slug != blank
        assign faq_material_words = faq_material_slug | replace: '-', ' ' | split: ' '
        assign faq_material = ''
        for word in faq_material_words
          assign faq_material_word = word | capitalize
          assign faq_material = faq_material | append: faq_material_word | append: ' '
        endfor
        assign faq_material = faq_material | strip
      endif
    endif

    assign faq_q1 = 'Is this an officially licensed Miró piece?'
    assign faq_a1 = 'Yes. This piece is part of the official Miró Collection, licensed by Successió Miró, and crafted in Spain by Joidart.'

    assign faq_q2 = 'What is ' | append: product.title | append: ' made from?'
    assign faq_a2 = product.title | append: ' is made from ' | append: faq_material | append: '.'

    assign faq_q3 = 'How do I care for this piece?'
    assign faq_a3 = 'An Atelier Modernista polishing cloth is enclosed with your purchase to help maintain your jewellery. Please limit exposure to water, fragrance, cosmetics, and chemicals, and remove the piece before showers, swimming, or exercise.'

    assign faq_q4 = 'What is your returns policy?'
    assign faq_a4 = '30-day returns are included with your purchase for most Atelier Modernista items, but please note that, in order to uphold the highest standards of hygiene and safety, pierced earrings are non-returnable. Luxury Gift Wrapping is also non-returnable.'

    assign faq_q5 = 'How much does UK shipping cost, and how long does delivery take?'
    assign faq_a5 = 'Orders dispatch within 1-2 days. Standard UK delivery costs £3.95, or is free for Atelier Circle members, and arrives within 1-4 days of dispatch. Express UK delivery is available for £7.95.'
  -%}

  <div class="am-faq">
    <div class="am-faq__heading" role="heading" aria-level="2">Questions about this piece</div>

    {%- if faq_is_miro -%}
      <details class="am-faq__item">
        <summary class="am-faq__question">{{ faq_q1 }}</summary>
        <div class="am-faq__answer"><p>{{ faq_a1 }}</p></div>
      </details>
    {%- endif -%}

    {%- if faq_material != blank -%}
      <details class="am-faq__item">
        <summary class="am-faq__question">{{ faq_q2 }}</summary>
        <div class="am-faq__answer"><p>{{ faq_a2 }}</p></div>
      </details>
    {%- endif -%}

    <details class="am-faq__item">
      <summary class="am-faq__question">{{ faq_q3 }}</summary>
      <div class="am-faq__answer"><p>{{ faq_a3 }}</p></div>
    </details>

    <details class="am-faq__item">
      <summary class="am-faq__question">{{ faq_q4 }}</summary>
      <div class="am-faq__answer"><p>{{ faq_a4 }}</p></div>
    </details>

    {%- unless faq_is_miro -%}
      <details class="am-faq__item">
        <summary class="am-faq__question">{{ faq_q5 }}</summary>
        <div class="am-faq__answer"><p>{{ faq_a5 }}</p></div>
      </details>
    {%- endunless -%}
  </div>

  <script type="application/ld+json">
  {
    "@context": "https://schema.org/",
    "@type": "FAQPage",
    "mainEntity": [
      {%- capture faq_json_entries -%}
        {%- if faq_is_miro -%}
          {"@type":"Question","name":{{ faq_q1 | json }},"acceptedAnswer":{"@type":"Answer","text":{{ faq_a1 | json }}}},
        {%- endif -%}
        {%- if faq_material != blank -%}
          {"@type":"Question","name":{{ faq_q2 | json }},"acceptedAnswer":{"@type":"Answer","text":{{ faq_a2 | json }}}},
        {%- endif -%}
        {"@type":"Question","name":{{ faq_q3 | json }},"acceptedAnswer":{"@type":"Answer","text":{{ faq_a3 | json }}}},
        {"@type":"Question","name":{{ faq_q4 | json }},"acceptedAnswer":{"@type":"Answer","text":{{ faq_a4 | json }}}}
        {%- unless faq_is_miro -%}
          ,{"@type":"Question","name":{{ faq_q5 | json }},"acceptedAnswer":{"@type":"Answer","text":{{ faq_a5 | json }}}}
        {%- endunless -%}
      {%- endcapture -%}
      {{ faq_json_entries }}
    ]
  }
  </script>

  <style>
  .am-faq{border-top:1px solid rgba(60,50,40,0.15);margin:2rem 0}
  .am-faq__heading{font-family:'Jost',sans-serif;font-size:14px;font-weight:500;letter-spacing:0.14em;text-transform:uppercase;color:#3C3228;margin:1.2rem 0 0.4rem}
  .am-faq__item{border-bottom:1px solid rgba(60,50,40,0.15)}
  .am-faq__question{display:flex;justify-content:space-between;align-items:center;padding:1rem 0;cursor:pointer;list-style:none;font-family:'Jost',sans-serif;font-size:14px;font-weight:400;letter-spacing:0.02em;color:#3C3228}
  .am-faq__question::-webkit-details-marker{display:none}
  .am-faq__question::after{content:'';width:10px;height:10px;border-right:1.5px solid currentColor;border-bottom:1.5px solid currentColor;transform:rotate(45deg);transition:transform 0.25s;flex-shrink:0}
  details[open] .am-faq__question::after{transform:rotate(-135deg)}
  .am-faq__answer{padding:0 0 1.2rem}
  .am-faq__answer p{font-family:'Cormorant Garamond',serif;font-size:1rem;font-weight:400;line-height:1.7;color:#3C3228;margin:0}
  </style>
{%- endif -%}
